export type ListComparisonsData = {
    body?: never;
    path?: never;
    query?: {
        runId?: string;
        limit?: number;
        offset?: number;
    };
    url: '/api/v1/comparisons';
};

export type ListComparisonsErrors = {
    /**
     * Missing, invalid, or expired bearer token
     */
    401: ProblemDetail;
    /**
     * The bearer token lacks a required simulation scope
     */
    403: ProblemDetail;
};

export type ListComparisonsError = ListComparisonsErrors[keyof ListComparisonsErrors];

export type ListComparisonsResponses = {
    /**
     * One page of comparisons
     */
    200: ComparisonList;
};

export type ListComparisonsResponse = ListComparisonsResponses[keyof ListComparisonsResponses];

export type CreateComparisonData = {
    body: ComparisonRequest;
    headers: {
        /**
         * UUID identifying one mutation request. Repeating a key with the same request representation returns the original resource; reusing it with a changed representation returns IDEMPOTENCY_CONFLICT.
         */
        'Idempotency-Key': string;
    };
    path?: never;
    query?: never;
    url: '/api/v1/comparisons';
};

export type CreateComparisonErrors = {
    /**
     * The comparison request is invalid, names a variant absent from its run's manifest, or names the same run and variant on both sides (code INVALID_COMPARISON)
     */
    400: ProblemDetail;
    /**
     * Missing, invalid, or expired bearer token
     */
    401: ProblemDetail;
    /**
     * The bearer token lacks a required simulation scope
     */
    403: ProblemDetail;
    /**
     * The requested resource does not exist or is not visible to the caller
     */
    404: ProblemDetail;
    /**
     * The idempotency key was reused with a different request (code IDEMPOTENCY_CONFLICT)
     */
    409: ProblemDetail;
    /**
     * The two sides' manifests differ in a gameplay-affecting definition; the detail names every differing definition (code INCOMPARABLE_RUNS)
     */
    422: ProblemDetail;
};

export type CreateComparisonError = CreateComparisonErrors[keyof CreateComparisonErrors];

export type CreateComparisonResponses = {
    /**
     * Comparison created
     */
    201: Comparison;
};

export type CreateComparisonResponse = CreateComparisonResponses[keyof CreateComparisonResponses];

